&lt;img title=&quot;Humano&#239;de&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Humano&#239;de.png&quot; style=&quot;opacity: 1&quot; /&gt;&lt;img title=&quot;Souterrain&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Souterrain.png&quot; style=&quot;opacity: 1&quot; /&gt;&lt;img title=&quot;Temp&#233;r&#233;&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Temp&#233;r&#233;.png&quot; style=&quot;opacity: 1&quot; /&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;i&gt;Source : &lt;a class=&quot;pagelink&quot; href=&quot;Codex-Monstrueux-(Contenu).html&quot; title=&quot;Codex monstrueux (Contenu)&quot;&gt;Codex monstrueux p.25&lt;/a&gt;&lt;/i&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;PX&lt;/b&gt; 6 400
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;a class=&quot;pagelink&quot; href=&quot;Drow.html&quot; title=&quot;Drow&quot;&gt;Drow&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;antipaladin&lt;/a&gt; 10
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;a class=&quot;pagelink&quot; href=&quot;Type-Humano&#239;de.html&quot; title=&quot;Humano&#239;de&quot;&gt;Humano&#239;de&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Elfe.html&quot; title=&quot;Elfe (sous-type)&quot;&gt;elfe&lt;/a&gt;) de taille M, CM
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Init&lt;/b&gt; +5 ; &lt;b&gt;Sens&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Dans-Le-Noir-(Capacit&#233;).html&quot; title=&quot;Vision dans le noir (Ext ou Sur)&quot;&gt;vision dans le noir&lt;/a&gt; &#224; 36 m ; &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +11
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Aura&lt;/b&gt; l&#226;chet&#233; (3 m), d&#233;sespoir (9 m)
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;D&#233;fense&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;CA&lt;/b&gt; 25, contact 11, pris au d&#233;pourvu 24 (armure +10, bouclier +4, Dex +1)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;pv&lt;/b&gt; 79 (10d10+20)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;R&#233;f&lt;/b&gt; +7, &lt;b&gt;Vig&lt;/b&gt; +11, &lt;b&gt;Vol&lt;/b&gt; +9 ; +2 contre les enchantements
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Immunit&#233;s&lt;/b&gt; maladie, sommeil ; &lt;b&gt;RM&lt;/b&gt; 16
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Faiblesses&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Aveugl&#233;-Par-La-Lumi&#232;re-(Capacit&#233;).html&quot; title=&quot;Aveugl&#233; par la lumi&#232;re (Ext)&quot;&gt;aveugl&#233; par la lumi&#232;re&lt;/a&gt;
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Attaque&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;VD&lt;/b&gt; 6 m
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Corps &#224; corps&lt;/b&gt; cimeterre +1, +16/+11 (1d6+5/15-20)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Distance&lt;/b&gt; arbal&#232;te lourde, +12 (1d10/19-20)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Attaques sp&#233;ciales&lt;/b&gt; canalisation d’&#233;nergie n&#233;gative (DD 18, 5d6), ch&#226;timent du Bien 4/jour (+3 attaque et CA, +10 d&#233;g&#226;ts)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Pouvoirs magiques&lt;/b&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;NLS&lt;/a&gt; 10 ; &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Concentration.html&quot; title=&quot;Concentration&quot;&gt;concentration&lt;/a&gt; +3)
&lt;/div&gt;
&lt;div class=&quot;BDsorts&quot;&gt;
1/jour — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lueur-F&#233;erique.html&quot; title=&quot;Lueur f&#233;erique&quot;&gt;lueur f&#233;erique&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lumi&#232;res-Dansantes.html&quot; title=&quot;Lumi&#232;res dansantes&quot;&gt;lumi&#232;res dansantes&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;T&#233;n&#232;bres.html&quot; title=&quot;T&#233;n&#232;bres&quot;&gt;t&#233;n&#232;bres&lt;/a&gt;&lt;/i&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Pouvoirs magiques&lt;/b&gt; d’antipaladin (&lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;NLS&lt;/a&gt; 10 ; &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Concentration.html&quot; title=&quot;Concentration&quot;&gt;concentration&lt;/a&gt; +13)
&lt;/div&gt;
&lt;div class=&quot;BDsorts&quot;&gt;
&#192; volont&#233; — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-Du-Bien.html&quot; title=&quot;D&#233;tection du Bien&quot;&gt;d&#233;tection du Bien&lt;/a&gt;&lt;/i&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Sorts d’antipaladin pr&#233;par&#233;s&lt;/b&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;NLS&lt;/a&gt; 7 ; &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Concentration.html&quot; title=&quot;Concentration&quot;&gt;concentration&lt;/a&gt; +10)
&lt;/div&gt;
&lt;div class=&quot;BDsorts&quot;&gt;
3e — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Litanie-De-Vision.html&quot; title=&quot;Litanie de vision&quot;&gt;litanie de vision&lt;/a&gt;&lt;/i&gt;
&lt;/div&gt;
&lt;div class=&quot;BDsorts&quot;&gt;
2e — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Invisibilit&#233;.html&quot; title=&quot;Invisibilit&#233;&quot;&gt;invisibilit&#233;&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Silence.html&quot; title=&quot;Silence&quot;&gt;silence&lt;/a&gt;&lt;/i&gt; (DD 15)
&lt;/div&gt;
&lt;div class=&quot;BDsorts&quot;&gt;
1er — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Litanie-De-Paresse.html&quot; title=&quot;Litanie de paresse&quot;&gt;litanie de paresse&lt;/a&gt;&lt;/i&gt; , &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ordre-Assassin.html&quot; title=&quot;Ordre assassin&quot;&gt;ordre assassin&lt;/a&gt;&lt;/i&gt; (DD 14), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Protection-Contre-Le-Bien.html&quot; title=&quot;Protection contre le Bien&quot;&gt;protection contre le Bien&lt;/a&gt;&lt;/i&gt;
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Tactique&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Avant le combat.&lt;/b&gt; Le champion d&#233;moniaque lance invisibilit&#233; et protection contre le Bien sur sa personne avant d’utiliser armure impie sur son harnois. Il utilise sa faveur des fi&#233;lons pour conf&#233;rer la propri&#233;t&#233; sp&#233;ciale anarchique, de feu, impie ou vicieuse &#224; son cimeterre.
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Pendant le combat.&lt;/b&gt; Le champion d&#233;moniaque utilise ch&#226;timent du Bien et ch&#226;timent canalis&#233; lorsqu’il attaque au cimeterre ou se rabat sur ses cruaut&#233;s et son toucher de corruption pour mettre ses adversaires hors de combat. Il lance silence pour neutraliser les lanceurs de sorts qui l’attaquent de loin.
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Caract&#233;ristiques&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;For&lt;/b&gt; 18, &lt;b&gt;Dex&lt;/b&gt; 12, &lt;b&gt;Con&lt;/b&gt; 12, &lt;b&gt;Int&lt;/b&gt; 12, &lt;b&gt;Sag&lt;/b&gt; 8, &lt;b&gt;Cha&lt;/b&gt; 16
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;BBA&lt;/b&gt; +10 ; &lt;b&gt;BMO&lt;/b&gt; +14 ; &lt;b&gt;DMD&lt;/b&gt; 25
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Dons&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Arme-De-Pr&#233;dilection.html&quot; title=&quot;Arme de pr&#233;dilection&quot;&gt;Arme de pr&#233;dilection&lt;/a&gt; (cimeterre), &lt;a class=&quot;pagelink&quot; href=&quot;Art-Du-Bouclier.html&quot; title=&quot;Art du bouclier&quot;&gt;Art du bouclier&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Ch&#226;timent-Canalis&#233;.html&quot; title=&quot;Ch&#226;timent canalis&#233;&quot;&gt;Ch&#226;timent canalis&#233;&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Science-De-Linitiative.html&quot; title=&quot;Science de l&amp;#39;initiative&quot;&gt;Science de l&#39;initiative&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Science-Du-Critique.html&quot; title=&quot;Science du critique&quot;&gt;Science du critique&lt;/a&gt; (cimeterre)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Comp&#233;tences&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt; +0, &lt;a class=&quot;pagelink&quot; href=&quot;Escalade.html&quot; title=&quot;Escalade&quot;&gt;Escalade&lt;/a&gt; +3, &lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt; +11, &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +11, &lt;a class=&quot;pagelink&quot; href=&quot;Psychologie.html&quot; title=&quot;Psychologie&quot;&gt;Psychologie&lt;/a&gt; +8
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Langues&lt;/b&gt; commun des profondeurs, elfique
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Particularit&#233;s&lt;/b&gt; cruaut&#233;s (h&#233;b&#233;t&#233;, naus&#233;eux, fi&#233;vreux, chancelant), faveur des fi&#233;lons (arme +2, 2/jour), utilisation des poisons, toucher de corruption 8/jour (5d6)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;&#201;quipement de combat&lt;/b&gt; &lt;i&gt;potion de &lt;a class=&quot;pagelink&quot; href=&quot;Soins-Importants.html&quot; title=&quot;Soins importants&quot;&gt;soins importants&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;potion de &lt;a class=&quot;pagelink&quot; href=&quot;Rapidit&#233;.html&quot; title=&quot;Rapidit&#233;&quot;&gt;rapidit&#233;&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;parchemin d’&lt;a class=&quot;pagelink&quot; href=&quot;Armure-Impie.html&quot; title=&quot;Armure impie&quot;&gt;armure impie&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;parchemin d’&lt;a class=&quot;pagelink&quot; href=&quot;Invisibilit&#233;.html&quot; title=&quot;Invisibilit&#233;&quot;&gt;invisibilit&#233;&lt;/a&gt;&lt;/i&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Armes-Alchimiques.html#Acide&quot; title=&quot;Armes alchimiques&quot;&gt;acide&lt;/a&gt; (2), &lt;a class=&quot;pagelink&quot; href=&quot;Armes-Alchimiques.html#Feu gr&#233;geois&quot; title=&quot;Armes alchimiques&quot;&gt;feu gr&#233;geois&lt;/a&gt; (2), &lt;a class=&quot;pagelink&quot; href=&quot;Outils-Alchimiques.html#Antitoxine&quot; title=&quot;Outils alchimiques&quot;&gt;antitoxine&lt;/a&gt; ; &lt;b&gt;&#201;quipement divers&lt;/b&gt; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Harnois-(Armure).html&quot; title=&quot;Harnois&quot;&gt;harnois&lt;/a&gt; +1&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;cu-(Armure).html&quot; title=&quot;&#201;cu (bois/acier)&quot;&gt;&#233;cu d’acier&lt;/a&gt; +1&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cimeterre-(Arme).html&quot; title=&quot;Cimeterre&quot;&gt;cimeterre&lt;/a&gt; +1&lt;/i&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Arbal&#232;te-Lourde-(Arme).html&quot; title=&quot;Arbal&#232;te lourde&quot;&gt;arbal&#232;te lourde&lt;/a&gt; avec 10 &lt;a class=&quot;pagelink&quot; href=&quot;Carreaux-Darbal&#232;te-(Arme).html&quot; title=&quot;Carreaux d&amp;#39;arbal&#232;te (10)&quot;&gt;carreaux&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes#Armesmaitre.html&quot; title=&quot;arme de ma&#238;tre&quot;&gt;de ma&#238;tre&lt;/a&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ceinturon-De-Force-De-G&#233;ant.html&quot; title=&quot;Ceinturon de force de g&#233;ant&quot;&gt;ceinturon de force de g&#233;ant&lt;/a&gt; +2&lt;/i&gt;, 69 po
&lt;/div&gt;&lt;br /&gt;&lt;/div&gt;&lt;/td&gt;
&lt;td&gt;&lt;div&gt;&lt;div style=&quot;float:right; background-color: #fff; padding: 0 0 0 0; margin: 0 0 4px 8px&quot;&gt;
&lt;table CLASS=&quot;tablo autoalt&quot;&gt;&lt;caption&gt;Variantes de drow&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;Nom&lt;/td&gt;&lt;td&gt;FP&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Capitaine-De-La-Maison-Drow.html&quot; title=&quot;Drow, Capitaine de la maison drow&quot;&gt;Capitaine de la maison drow&lt;/a&gt;&lt;/td&gt;&lt;td&gt;6&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Champion-D&#233;moniaque-Drow.html&quot; title=&quot;Drow, Champion d&#233;moniaque drow&quot;&gt;Champion d&#233;moniaque drow&lt;/a&gt;&lt;/td&gt;&lt;td&gt;9&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Drow.html&quot; title=&quot;Drow&quot;&gt;Drow&lt;/a&gt;&lt;/td&gt;&lt;td&gt;1/3&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Drow-Noble.html&quot; title=&quot;Drow noble&quot;&gt;Drow noble&lt;/a&gt;&lt;/td&gt;&lt;td&gt;3&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;claireur-Drow.html&quot; title=&quot;Drow, &#201;claireur drow&quot;&gt;&#201;claireur drow&lt;/a&gt;&lt;/td&gt;&lt;td&gt;1&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Empoisonneur-Drow.html&quot; title=&quot;Drow, Empoisonneur drow&quot;&gt;Empoisonneur drow&lt;/a&gt;&lt;/td&gt;&lt;td&gt;11&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Garde-De-La-Maison-Drow.html&quot; title=&quot;Drow, Garde de la maison drow&quot;&gt;Garde de la maison drow&lt;/a&gt;&lt;/td&gt;&lt;td&gt;2&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-&#201;claireur-Drow.html&quot; title=&quot;Drow, Ma&#238;tre &#233;claireur drow&quot;&gt;Ma&#238;tre &#233;claireur drow&lt;/a&gt;&lt;/td&gt;&lt;td&gt;7&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Matrone-Drow.html&quot; title=&quot;Drow, Matrone drow&quot;&gt;Matrone drow&lt;/a&gt;&lt;/td&gt;&lt;td&gt;15&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;unknownlink&quot; href=&quot;Pr&#234;tresse-Drow.html&quot; title=&quot;Pathfinder-RPG.Pr&#234;tresse drow&quot;&gt;Pr&#234;tresse drow&lt;/a&gt;&lt;/td&gt;&lt;td&gt;5&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;Le champion d&#233;moniaque a &#233;t&#233; choisi par les plus puissants des nobles pour leur servir de g&#233;n&#233;ral et de garde du corps. Il incarne la brutalit&#233;, la cruaut&#233; et les pulsions meurtri&#232;res instill&#233;es chez les drows et si appr&#233;ci&#233;es au sein de leur soci&#233;t&#233;.&lt;br /&gt;&lt;br /&gt;Les Abysses ont mis le champion d&#233;moniaque &#224; l’&#233;preuve et cela l’a rendu plus fort. Son &#226;me est marqu&#233;e de si&#232;cles de d&#233;pravation et il est irr&#233;m&#233;diablement vou&#233; au mal, ce qu’il est ravi de prouver. Il b&#233;n&#233;ficie d’un grand confort au sein de la soci&#233;t&#233; drow gr&#226;ce au butin ramen&#233; de la guerre, mais sa soif de sang le pousse toujours &#224; repartir au combat.
&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
